def fetch_all_contacts(relationship=None):
    contacts_by_id={}
    i=0
    while True:
        kwargs={'access_token': phone_token, 'page_index': i, 'page_limit': 20}
        if relationship is not None:
            kwargs['relationship']=relationship
        res=apis.phone.search_contacts(**kwargs)
        if not res:
            break
        for c in res:
            contacts_by_id[c['contact_id']]=c
        if len(res)<kwargs['page_limit']:
            # Might still paginate; safer to rely on empty, but keep going one more check.
            pass
        i+=1
    return list(contacts_by_id.values())

# total contacts (no relationship filter)
total_contacts=fetch_all_contacts(relationship=None)
print('total_contacts', len(total_contacts))

roommate_contacts=fetch_all_contacts(relationship='roommate')
print('roommate_contacts', len(roommate_contacts))

coworker_contacts=fetch_all_contacts(relationship='coworker')
print('coworker_contacts', len(coworker_contacts))

# Build email set for action matching
emails=set()
for c in roommate_contacts+coworker_contacts:
    if c.get('email'):
        emails.add(c['email'])
print('matched_emails_count', len(emails))
print('sample_emails', sorted(list(emails))[:10])

